// Edit only this symbol. The manual trigger creates exactly one observation.
const symbol = 'BTC';
if (!/^[A-Z0-9]{1,20}$/.test(symbol)) {
  throw new Error('INPUT_INVALID: use an uppercase crypto symbol.');
}
return [{ json: { symbol } }];

function toolBody(response) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  if (!object(response) || response.error !== undefined || response.isError === true) {
    throw new Error('UNVERIFIED: the MCP call returned an error. No observation is approved.');
  }
  let body = response.structuredContent;
  if (body === undefined) {
    const content = response.content;
    if (!Array.isArray(content) || content.length !== 1 || content[0].type !== 'text') {
      throw new Error('UNVERIFIED: missing or ambiguous MCP result.');
    }
    body = content[0].text;
    if (typeof body === 'string') {
      if (body.length > 32768) throw new Error('UNVERIFIED: oversized MCP result.');
      try { body = JSON.parse(body); }
      catch { throw new Error('UNVERIFIED: the MCP result is not JSON.'); }
    }
  }
  if (!object(body) || body.error !== undefined || body.success === false || JSON.stringify(body).length > 32768) {
    throw new Error('UNVERIFIED: the MCP result is unavailable or malformed.');
  }
  return body;
}

const items = $input.all();
if (items.length !== 1) throw new Error('UNVERIFIED: expected one price result.');
const print = toolBody(items[0].json);
const requestedSymbol = $('Choose symbol').first().json.symbol;
const signature = /^[A-Za-z0-9+/]{86}==$/;
if (print.symbol !== requestedSymbol || typeof print.price !== 'number' || !Number.isFinite(print.price)
    || print.price <= 0 || typeof print.at !== 'string' || !Number.isFinite(Date.parse(print.at))
    || !['consensus', 'blended', 'indicative', 'composite', 'single-source'].includes(print.grade)
    || typeof print.signature !== 'string' || !signature.test(print.signature)
    || !print.v2 || print.v2.sig !== 'pulse-index-v2'
    || typeof print.v2.signature !== 'string' || !signature.test(print.v2.signature)
    || typeof print.v2.canonical !== 'string' || print.v2.canonical.length > 8192
    || typeof print.v2.kid !== 'string' || !/^[A-Za-z0-9._:-]{1,64}$/.test(print.v2.kid)) {
  throw new Error('UNVERIFIED: a complete signed price record is required.');
}
if (print.priceText !== undefined && (typeof print.priceText !== 'string' || !print.priceText.length
    || print.priceText.length > 100 || Number(print.priceText) !== print.price)) {
  throw new Error('UNVERIFIED: price and exact price text disagree.');
}
// Keep every byte of priceText and v2.canonical unchanged. The verifier takes
// the print fields at the top level, not an object nested under "print".
return [{ json: { print }, pairedItem: { item: 0 } }];

function toolBody(response) {
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  if (!object(response) || response.error !== undefined || response.isError === true) {
    throw new Error('UNVERIFIED: the MCP call returned an error. No observation is approved.');
  }
  let body = response.structuredContent;
  if (body === undefined) {
    const content = response.content;
    if (!Array.isArray(content) || content.length !== 1 || content[0].type !== 'text') {
      throw new Error('UNVERIFIED: missing or ambiguous MCP result.');
    }
    body = content[0].text;
    if (typeof body === 'string') {
      if (body.length > 32768) throw new Error('UNVERIFIED: oversized MCP result.');
      try { body = JSON.parse(body); }
      catch { throw new Error('UNVERIFIED: the MCP result is not JSON.'); }
    }
  }
  if (!object(body) || body.error !== undefined || body.success === false || JSON.stringify(body).length > 32768) {
    throw new Error('UNVERIFIED: the MCP result is unavailable or malformed.');
  }
  return body;
}

const items = $input.all();
if (items.length !== 1) throw new Error('UNVERIFIED: expected one verification result.');
const result = toolBody(items[0].json);
const print = $('Preserve signed print').first().json.print;
// Strict booleans: a string "true", v1-only valid, or a missing field fails.
if (result.recordValid !== true || result.valid !== true || result.metadataSigned !== true
    || result.verificationScope !== 'full-record' || result.v2?.valid !== true
    || result.v2?.signatureValid !== true || result.v2?.fieldsMatch !== true
    || !Array.isArray(result.v2.mismatches) || result.v2.mismatches.length !== 0) {
  throw new Error('UNVERIFIED: full-record signature verification did not pass.');
}
const expectedCheck = ['pulse-index-v1', print.symbol, print.priceText ?? String(print.price), print.at, print.grade].join('\n');
if (result.checked !== expectedCheck || result.v2.verifiedWithKid !== print.v2.kid
    || (print.kid !== undefined && result.verifiedWithKid !== print.kid)) {
  throw new Error('UNVERIFIED: the verification does not match this price record.');
}
const fields = ['symbol', 'price', 'priceText', 'at', 'grade', 'engine', 'sources', 'tier',
  'confidence', 'dispersionBps', 'interval.lower', 'interval.upper', 'cadence.band',
  'cadence.calculatedAgeMs', 'cadence.newestSourceAgeMs', 'cadence.oldestSourceAgeMs',
  'cadence.p50UpdateMs', 'cadence.p95UpdateMs'];
const signed = result.v2.signedFields;
if (!signed || typeof signed !== 'object' || Array.isArray(signed)
    || Object.keys(signed).length !== fields.length) {
  throw new Error('UNVERIFIED: expected the complete live-record field set.');
}
for (const path of fields) {
  const value = path.split('.').reduce((object, key) => object?.[key], print) ?? null;
  if (!Object.prototype.hasOwnProperty.call(signed, path) || signed[path] !== value) {
    throw new Error('UNVERIFIED: signed fields differ from this observation.');
  }
}
return [{ json: {
  status: 'VERIFIED',
  source: 'Pulse Verity Index',
  verificationMeaning: 'Signatures and covered record fields match. Freshness and suitability require separate checks.',
  signedFields: signed,
  signedPrint: print,
  verification: {
    recordValid: true, verificationScope: result.verificationScope,
    verifiedWithKid: result.verifiedWithKid, v2VerifiedWithKid: result.v2.verifiedWithKid,
    performedBy: 'Hosted Pulse Verity MCP verify_print'
  }
}, pairedItem: { item: 0 } }];
